<?php
require_once __DIR__ . '/../app/layout.php';$u=require_role(['admin','ngo','demand_reporter','restaurant','event_organizer']);$pdo=db();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
$params=[$from.' 00:00:00',$to.' 23:59:59'];$where='sf.created_at BETWEEN ? AND ?';
if($u['role']!=='admin'){$where.=' AND (sf.restaurant_id=? OR EXISTS (SELECT 1 FROM donation_requests access_dr WHERE access_dr.surplus_food_id=sf.id AND access_dr.requested_by=?))';$params[]=$u['id'];$params[]=$u['id'];}
$sql="SELECT sf.category,COUNT(*) AS listings,COALESCE(SUM(sf.quantity_kg),0) AS donated_kg,COALESCE(SUM(CASE WHEN sf.status='expired' THEN sf.quantity_kg ELSE 0 END),0) AS expired_kg,SUM(COALESCE((SELECT SUM(dr.quantity_kg) FROM donation_requests dr WHERE dr.surplus_food_id=sf.id AND dr.status IN ('delivered','completed') AND dr.updated_at BETWEEN ? AND ?),0)) AS delivered_kg FROM surplus_food sf WHERE $where GROUP BY sf.category ORDER BY donated_kg DESC";
$q=$pdo->prepare($sql);$q->execute(array_merge([$from.' 00:00:00',$to.' 23:59:59'],$params));$rows=$q->fetchAll();
$summary=['listings'=>0,'donated'=>0.0,'delivered'=>0.0,'expired'=>0.0];foreach($rows as $r){$summary['listings']+=(int)$r['listings'];$summary['donated']+=(float)$r['donated_kg'];$summary['delivered']+=(float)$r['delivered_kg'];$summary['expired']+=(float)$r['expired_kg'];}
// Expired listing quantity is an indicator, not proof that food was discarded.
page_header('Food waste analytics'); ?>
<div class="page-intro"><div class="eyebrow">DATA-DRIVEN IMPACT</div><h1>Food waste <em>analytics.</em></h1><p>Explore listing, delivery and expiry indicators from recorded database activity. Expired quantity is not automatically proof of food that was discarded.</p></div>
<form method="get" class="form-panel form-grid"><label>From date<input type="date" name="from" value="<?=e($from)?>" required></label><label>To date<input type="date" name="to" value="<?=e($to)?>" required></label><div class="full"><button class="btn" type="submit">Apply filters</button> <a class="btn btn-outline" href="<?=e(url('waste_analytics.php'))?>">Reset</a></div></form>
<div class="dashboard-stats"><div class="stat-card"><div class="stat-label">Listings</div><div class="stat-number"><?=number_format($summary['listings'])?></div></div><div class="stat-card"><div class="stat-label">Listed quantity (kg)*</div><div class="stat-number"><?=number_format($summary['donated'],2)?></div></div><div class="stat-card"><div class="stat-label">Delivered quantity (kg)**</div><div class="stat-number"><?=number_format($summary['delivered'],2)?></div></div><div class="stat-card"><div class="stat-label">Expired listing quantity (kg)</div><div class="stat-number"><?=number_format($summary['expired'],2)?></div></div></div>
<div class="notice-panel"><strong>How to read these metrics</strong><p>*Listed quantity is based on food listings in the selected period. **Delivered quantity is summed from donation requests and can include multiple requests against one listing. It is not a deduplicated waste mass. Confirmed waste needs an explicit waste record; this release does not infer it from expiry.</p></div>
<div class="section-heading"><div><div class="eyebrow">CATEGORY BREAKDOWN</div><h2>Recorded activity by food category</h2></div></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Listings</th><th>Listed kg</th><th>Delivered request kg</th><th>Expired listing kg</th><th>Share of listed kg</th></tr></thead><tbody><?php foreach($rows as $r):$share=$summary['donated']>0?((float)$r['donated_kg']/$summary['donated']*100):0;?><tr><td><?=e($r['category'])?></td><td><?=(int)$r['listings']?></td><td><?=number_format((float)$r['donated_kg'],2)?></td><td><?=number_format((float)$r['delivered_kg'],2)?></td><td><?=number_format((float)$r['expired_kg'],2)?></td><td><div class="bar"><i style="width:<?=min(100,max(0,$share))?>%"></i></div><small><?=number_format($share,1)?>%</small></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="table-empty">No food records for this date range.</td></tr><?php endif;?></tbody></table></div>
<p class="muted">Analytics uses current records; changes to old listings can affect historical totals. For a verified waste-reduction claim, add explicit weighing and disposal-confirmation records.</p><?php page_footer(); ?>
